mapper.select:
select r.record_id, r.customer_id, r.follow_type, r.content, r.follow_time, r.next_follow_time, r.visit_count, r.companion, r.reception_user_id, r.visit_purpose, r.feedback, r.create_by, r.create_time, r.remark, u.nick_name as create_by_name, ru.nick_name as reception_user_name, c.customer_name, c.phone from crm_follow_record r left join sys_user u on u.user_name = r.create_by left join sys_user ru on ru.user_id = r.reception_user_id left join crm_customer c on c.customer_id = r.customer_id
and r.customer_id = #{customerId}
and r.follow_type = #{followType}
and c.customer_name like concat('%', #{customerName}, '%')
and r.follow_time >= #{params.beginTime}
and r.follow_time <= #{params.endTime}
order by r.follow_time desc
